pub const CUSTOM_MENUS: &[&str] = &[
    "orechests:gold_chest",
    "orechests:diamond_chest",
    "orechests:netherite_chest",
];

fn write_if_changed(path: &Path, content: &[u8]) {
    let needs_write = fs::read(path).map_or(true, |existing| existing != content);
    if needs_write {
        let _ = fs::write(path, content);
    }
}

/// Ensures custom chest menu IDs are registered in `registries.json` under `minecraft:menu`
/// so both server (`ServerData::load`) and client (`remote.rs`) resolve the same protocol IDs.
fn patch_registries_json(reg_path: &Path) {
    let Ok(bytes) = fs::read(reg_path) else {
        return;
    };
    let Ok(mut doc) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
        return;
    };
    let Some(entries) = doc
        .get_mut("minecraft:menu")
        .and_then(|m| m.get_mut("entries"))
        .and_then(|e| e.as_object_mut())
    else {
        return;
    };

    if CUSTOM_MENUS.iter().all(|m| entries.contains_key(*m)) {
        return;
    }

    let mut next_id = entries
        .values()
        .filter_map(|v| v.get("protocol_id").and_then(|id| id.as_u64()))
        .max()
        .map_or(0, |max| max + 1);

    for &menu in CUSTOM_MENUS {
        if !entries.contains_key(menu) {
            entries.insert(
                menu.to_owned(),
                serde_json::json!({ "protocol_id": next_id }),
            );
            next_id += 1;
        }
    }

    if let Ok(out) = serde_json::to_vec(&doc) {
        let _ = fs::write(reg_path, out);
    }
}

pub fn ensure_content_and_recipes(root: &Path) {
    patch_registries_json(&root.join("registries.json"));
    if let Some(found) = horizon_protocol::registry::Builtin::find(root) {
        patch_registries_json(&found);
    }
    if let Ok(here) = std::env::current_dir() {
        patch_registries_json(&here.join(".horizon-cache/mod-content/registries.json"));
    }

    let mc_recipe_dir = root.join("data/minecraft/recipe");
    let ore_recipe_dir = root.join("data/orechests/recipe");
    let _ = fs::create_dir_all(&mc_recipe_dir);
    let _ = fs::create_dir_all(&ore_recipe_dir);

    // Clean up obsolete recipes from previous versions
    if let Ok(entries) = fs::read_dir(&ore_recipe_dir) {
        for entry in entries.flatten() {
            let file_name = entry.file_name();
            let name = file_name.to_string_lossy();
            if !RECIPES.iter().any(|(r, _)| *r == name) {
                let _ = fs::remove_file(entry.path());
            }
        }
    }
    if let Ok(entries) = fs::read_dir(&mc_recipe_dir) {
        for entry in entries.flatten() {
            let file_name = entry.file_name();
            let name = file_name.to_string_lossy();
            if let Some(stripped) = name.strip_prefix("orechests_") {
                if !RECIPES.iter().any(|(r, _)| *r == stripped) {
                    let _ = fs::remove_file(entry.path());
                }
            }
        }
    }

    for (name, content) in RECIPES {
        let mc_dest = mc_recipe_dir.join(format!("orechests_{name}"));
        let ore_dest = ore_recipe_dir.join(name);
        write_if_changed(&mc_dest, content.as_bytes());
        write_if_changed(&ore_dest, content.as_bytes());
    }

    // Ensure orechests is listed in horizon-mod-content.json
    let marker_path = root.join("horizon-mod-content.json");
    let mut namespaces: Vec<String> = fs::read(&marker_path)
        .ok()
        .and_then(|b| serde_json::from_slice(&b).ok())
        .unwrap_or_default();
    if !namespaces.iter().any(|ns| ns == ID) {
        namespaces.push(ID.to_owned());
        if let Ok(bytes) = serde_json::to_vec(&namespaces) {
            write_if_changed(&marker_path, &bytes);
        }
    }
}

pub fn auto_discover_root() -> Option<PathBuf> {
    if let Ok(exe) = std::env::current_exe() {
        let mut cur = exe.parent();
        while let Some(dir) = cur {
            if dir.join("data/minecraft/recipe").is_dir() {
                return Some(dir.to_path_buf());
            }
            if dir.join(".local/horizon-client/26.3").is_dir() {
                return Some(dir.join(".local/horizon-client/26.3"));
            }
            cur = dir.parent();
        }
    }
    None
}

