pub fn ensure_content_mod_installed() {
    if let Ok(here) = std::env::current_dir() {
        let mods_dir = here.join("horizon-mods");
        let _ = fs::create_dir_all(&mods_dir);
        let hmod_path = mods_dir.join("orechests.hmod");
        write_if_changed(&hmod_path, HMOD_BYTES);

        let mods_txt = here.join("horizon-mods.txt");
        let content = fs::read_to_string(&mods_txt).unwrap_or_default();
        if !content.lines().any(|l| l.trim() == "mod.orechests:true") {
            let new_content = if content.is_empty() {
                "mod.orechests:true\n".to_string()
            } else if content.ends_with('\n') {
                format!("{content}mod.orechests:true\n")
            } else {
                format!("{content}\nmod.orechests:true\n")
            };
            let _ = fs::write(&mods_txt, new_content);
        }
    }
}
